import React from "react";

function MainMenu() {
    const containerStyle = { display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 15, padding: "20px" };
    const itemStyle = { background: "white", padding: 25, borderRadius: 25, textDecoration: "none", color: "#2D3436", boxShadow: "0 4px 12px rgba(0,0,0,0.03)" };
    const iconStyle = { width: 45, height: 45, borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 15, background: "rgba(168,35,36,0.1)" };

    const menuItems = [
        { label: "Calendar", icon: "calendar_today" },
        { label: "Layout", icon: "grid_view" },
        { label: "Events", icon: "event" },
        { label: "Stats", icon: "insights" },
    ];

    return (
        <div style={containerStyle}>
            {menuItems.map((item) => (
                <div key={item.label} style={itemStyle}>
                    <div style={iconStyle}><span className="material-icons-round">{item.icon}</span></div>
                    <div>{item.label}</div>
                </div>
            ))}
        </div>
    );
}

export default MainMenu;
